  if (env.APP_HOST !== undefined) out.host = env.APP_HOST;
  if (env.APP_LOG_LEVEL !== undefined || env.APP_LOG_PRETTY !== undefined) {
    out.log = {};
    if (env.APP_LOG_LEVEL !== undefined) {
      const level = env.APP_LOG_LEVEL.toLowerCase();
