import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadConfig } from '../src/index.ts';

test('defaults only', () => {
  assert.deepEqual(loadConfig(), { port: 8080, host: 'localhost', log: { level: 'info', pretty: false }, features: ['search'] });
});

test('file overrides defaults', () => {
  const cfg = loadConfig({ fileText: JSON.stringify({ host: '0.0.0.0', log: { pretty: true } }) });
  assert.equal(cfg.host, '0.0.0.0');
  assert.deepEqual(cfg.log, { level: 'info', pretty: true });
});

test('env overrides file', () => {
  const cfg = loadConfig({
    env: { APP_HOST: 'api.internal', APP_LOG_LEVEL: 'warn' },
    fileText: JSON.stringify({ host: '0.0.0.0', log: { level: 'debug', pretty: true } }),
  });
  assert.equal(cfg.host, 'api.internal');
  assert.deepEqual(cfg.log, { level: 'warn', pretty: true });
});

test('file pins the port for blue/green deploys', () => {
  // The deploy pipeline writes the slot port into config.json; it must not be clobbered.
  const cfg = loadConfig({ env: { APP_PORT: '3000' }, fileText: JSON.stringify({ port: 9001 }) });
  assert.equal(cfg.port, 9001);
});

test('env port is used when the file has none', () => {
  const cfg = loadConfig({ env: { APP_PORT: '3000' }, fileText: '{}' });
  assert.equal(cfg.port, 3000);
});

test('features from env replace the defaults', () => {
  assert.deepEqual(loadConfig({ env: { APP_FEATURES: 'billing' } }).features, ['billing']);
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { deepMerge } from '../src/merge.ts';

test('top-level override', () => {
  assert.deepEqual(deepMerge({ a: 1, b: 2 }, { b: 3 }), { a: 1, b: 3 });
});

test('nested objects merge key by key', () => {
  assert.deepEqual(deepMerge({ log: { level: 'info', pretty: false } }, { log: { level: 'debug' } }), { log: { level: 'debug', pretty: false } });
});

test('arrays are replaced', () => {
  assert.deepEqual(deepMerge({ features: ['a', 'b'] }, { features: ['c'] }), { features: ['c'] });
});

test('undefined override values are ignored', () => {
  assert.deepEqual(deepMerge({ a: 1 }, { a: undefined }), { a: 1 });
});

test('inputs are not mutated', () => {
  const base = { log: { level: 'info', pretty: false } };
  const override = { log: { pretty: true } };
  deepMerge(base, override);
  assert.deepEqual(base, { log: { level: 'info', pretty: false } });
  assert.deepEqual(override, { log: { pretty: true } });
});
# svc-config

Loads the service configuration from three layers:

1. built-in defaults (`src/defaults.ts`)
2. the deployment's `config.json` (`src/file.ts`)
3. environment variables (`src/env.ts`)

**Precedence: environment variables always win over the config file, and the config file
wins over the defaults.** This is what lets ops override any setting at deploy time
without rebuilding the image.

Nested objects are merged key by key; arrays are replaced, not concatenated.

Supported variables: `APP_PORT` (number), `APP_HOST`, `APP_LOG_LEVEL`, `APP_LOG_PRETTY`
(`true`/`false`), `APP_FEATURES` (comma-separated).

